static int isSafe(int *cols, int row, int col) {
  for (int r = 0; r < row; r++) {
    if (cols[r] == col || abs(cols[r] - col) == abs(r - row)) return 0;
  }
  return 1;
}

static void backtrack(int n, int row, int *cols, char ***res, int *size, int **colSizes) {
  if (row == n) {
    char **board = (char **)malloc(sizeof(char *) * n);
    for (int i = 0; i < n; i++) {
      board[i] = (char *)malloc(n + 1);
      for (int j = 0; j < n; j++) board[i][j] = '.';
      board[i][cols[i]] = 'Q';
      board[i][n] = '\0';
    }
    res[*size] = board;
    (*colSizes)[*size] = n;
    (*size)++;
    return;
  }
  for (int col = 0; col < n; col++) {
    if (isSafe(cols, row, col)) {
      cols[row] = col;
      backtrack(n, row + 1, cols, res, size, colSizes);
    }
  }
}

char ***solveNQueens(int n, int *returnSize, int **returnColumnSizes) {
  char ***res = (char ***)malloc(sizeof(char **) * 10000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 10000);
  int *cols = (int *)malloc(sizeof(int) * n);
  *returnSize = 0;
  backtrack(n, 0, cols, res, returnSize, returnColumnSizes);
  free(cols);
  return res;
}

class Solution {
  bool isSafe(vector<int> &cols, int row, int col) {
    for (int r = 0; r < row; r++) {
      if (cols[r] == col || abs(cols[r] - col) == abs(r - row)) return false;
    }
    return true;
  }

  void backtrack(int n, int row, vector<int> &cols, vector<vector<string>> &res) {
    if (row == n) {
      vector<string> board(n, string(n, '.'));
      for (int i = 0; i < n; i++) board[i][cols[i]] = 'Q';
      res.push_back(board);
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(cols, row, col)) {
        cols[row] = col;
        backtrack(n, row + 1, cols, res);
      }
    }
  }

public:
  vector<vector<string>> solveNQueens(int n) {
    vector<vector<string>> res;
    vector<int> cols(n, -1);
    backtrack(n, 0, cols, res);
    return res;
  }
};

func solveNQueens(n int) [][]string {
	var res [][]string
	cols := make([]int, n)
	var isSafe func(row, col int) bool
	isSafe = func(row, col int) bool {
		for r := 0; r < row; r++ {
			if cols[r] == col || abs(cols[r]-col) == abs(r-row) {
				return false
			}
		}
		return true
	}
	var backtrack func(row int)
	backtrack = func(row int) {
		if row == n {
			board := make([]string, n)
			for i := 0; i < n; i++ {
				line := make([]byte, n)
				for j := 0; j < n; j++ {
					line[j] = '.'
				}
				line[cols[i]] = 'Q'
				board[i] = string(line)
			}
			res = append(res, board)
			return
		}
		for col := 0; col < n; col++ {
			if isSafe(row, col) {
				cols[row] = col
				backtrack(row + 1)
			}
		}
	}
	backtrack(0)
	return res
}

