class Solution {
  private boolean isSafe(int[] cols, int row, int col) {
    for (int r = 0; r < row; r++) {
      if (cols[r] == col || Math.abs(cols[r] - col) == Math.abs(r - row)) return false;
    }
    return true;
  }

  private void backtrack(int n, int row, int[] cols, List<List<String>> res) {
    if (row == n) {
      List<String> board = new ArrayList<>();
      for (int i = 0; i < n; i++) {
        char[] line = new char[n];
        Arrays.fill(line, '.');
        line[cols[i]] = 'Q';
        board.add(new String(line));
      }
      res.add(board);
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(cols, row, col)) {
        cols[row] = col;
        backtrack(n, row + 1, cols, res);
      }
    }
  }

  public List<List<String>> solveNQueens(int n) {
    List<List<String>> res = new ArrayList<>();
    backtrack(n, 0, new int[n], res);
    return res;
  }
}

class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        res = []
        cols = [-1] * n

        def is_safe(row: int, col: int) -> bool:
            for r in range(row):
                if cols[r] == col or abs(cols[r] - col) == abs(r - row):
                    return False
            return True

        def backtrack(row: int):
            if row == n:
                board = []
                for i in range(n):
                    line = ["."] * n
                    line[cols[i]] = "Q"
                    board.append("".join(line))
                res.append(board)
                return
            for col in range(n):
                if is_safe(row, col):
                    cols[row] = col
                    backtrack(row + 1)

        backtrack(0)
        return res

impl Solution {
  pub fn solve_n_queens(n: i32) -> Vec<Vec<String>> {
    fn is_safe(cols: &[i32], row: i32, col: i32) -> bool {
      for r in 0..row {
        if cols[r as usize] == col || (cols[r as usize] - col).abs() == (r - row).abs() {
          return false;
        }
      }
      true
    }
    fn backtrack(n: i32, row: i32, cols: &mut Vec<i32>, res: &mut Vec<Vec<String>>) {
      if row == n {
        let mut board = vec![];
        for i in 0..n {
          let mut line = vec![b'.'; n as usize];
          line[cols[i as usize] as usize] = b'Q';
          board.push(String::from_utf8(line).unwrap());
        }
        res.push(board);
        return;
      }
      for col in 0..n {
        if is_safe(cols, row, col) {
          cols[row as usize] = col;
          backtrack(n, row + 1, cols, res);
        }
      }
    }
    let mut res = vec![];
    let mut cols = vec![-1; n as usize];
    backtrack(n, 0, &mut cols, &mut res);
    res
  }
}

const solveNQueens = (n: number): string[][] => {
  const res: string[][] = [];
  const cols: number[] = new Array(n).fill(-1);
  const isSafe = (row: number, col: number): boolean => {
    for (let r = 0; r < row; r++) {
      if (cols[r] === col || Math.abs(cols[r] - col) === Math.abs(r - row)) return false;
    }
    return true;
  };
  const backtrack = (row: number) => {
    if (row === n) {
      const board: string[] = [];
      for (let i = 0; i < n; i++) {
        const line = new Array(n).fill('.');
        line[cols[i]] = 'Q';
        board.push(line.join(''));
      }
      res.push(board);
      return;
    }
    for (let col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        cols[row] = col;
        backtrack(row + 1);
      }
    }
  };
  backtrack(0);
  return res;
};
